$(".delete-testimonial").on("click",function(event){event.preventDefault();let $this=$(this),target=$this.data("id"),link=$this.data("url");$Confirm({},function(result){result.value&&fetch(link,{headers:{"Content-Type":"application/json;charset=utf-8"}}).then(res=>res.json()).then(response=>{response.success&&$this.parents(`tr#tr-${target}`).remove()}).catch(error=>$notification.error("",error.message,2e3,"fa fa-exclamation-circle"))})});